// The Inspector's real-world view: the structure generated by the GAME's own world code, not drawn by the
// Inspector, so what you see is what a player would find.
//
// DOM-free (the page supplies a texture manager), so the building, the loot and block-entity views and the
// walk-through start can all be tested in Node.
import { createAuditWorld } from './structureAudit.js';
import { locateNearestStructure } from './worldStructures.js';
import { structureArrival, ensureBoxLoaded } from './teleport.js';
import { BLOCKS, BLOCK_DEFS } from './blocks.js';
import { inspectorStructures } from './structureInspectorSession.js';

/**
 * Generate a structure in a real `World` and report where it is.
 *
 * @param {object} options
 * @param {string} options.structureId
 * @param {number|string} [options.seed]
 * @param {string} [options.biome]       the world's biome selection; 'all' lets the structure's own biome gate decide
 * @param {number} [options.margin]      chunks of terrain generated around the structure's box
 */
export async function buildStructureWorld({ structureId, seed = 20250401, biome = 'auto', difficulty = 'normal', margin = 1, maxRadiusChunks = 512, mixedRadiusChunks = 48 }) {
  // 'auto': look for one in a normal mixed-biome world first, but only nearby, because searching a big radius through
  // the real biome noise takes minutes (buried treasure, mansions, ...). If none is near, build a world made of the
  // structure's own biome, where it is found at once. `built.biomeMode` says which one you are looking at.
  let world; let recorder; let found; let biomeMode = 'mixed';
  const attempt = async (worldBiome, radius) => {
    ({ world, recorder } = await createAuditWorld({ seed, biome: worldBiome, structureId, difficulty }));
    found = locateNearestStructure(world, structureId, 0, 0, { maxRadiusChunks: radius });
  };
  const own = inspectorStructures().find((entry) => entry.id === structureId)?.defaultBiome ?? 'plains';
  const otherDimension = ['nether', 'the_end'].includes(inspectorStructures().find((entry) => entry.id === structureId)?.dimension);
  if (biome === 'auto' && otherDimension) {
    // A mixed world is the Overworld; a Nether or End structure needs a world of its own dimension.
    biomeMode = `${own} only`;
    await attempt(own, maxRadiusChunks);
  } else if (biome === 'auto') {
    try { await attempt('all', mixedRadiusChunks); } catch (error) {
      biomeMode = `${own} only`;
      await attempt(own, maxRadiusChunks);
    }
  } else {
    biomeMode = biome === 'all' ? 'mixed' : `${biome} only`;
    await attempt(biome, maxRadiusChunks);
  }
  // Load margin + 1 so every meshed chunk has its neighbours (the mesher culls faces against them).
  ensureBoxLoaded(world, found.box, margin + 1);
  const [minX, minY, minZ, maxX, maxY, maxZ] = found.box;
  const range = {
    minCx: Math.floor(minX / 16) - margin, maxCx: Math.floor(maxX / 16) + margin,
    minCz: Math.floor(minZ / 16) - margin, maxCz: Math.floor(maxZ / 16) + margin
  };
  const arrival = structureArrival(world, found);
  // The piece boxes, for the page's overlay and the evidence file (`locateNearestStructure` reports only the whole box).
  const start = world.structures.engine.locate(structureId, 0, 0, { maxRadiusChunks }).start;
  const pieces = start.pieces.map((piece) => piece.box.toArray());
  return {
    structureId, seed: String(seed), world, recorder, found, range, arrival, pieces, biomeMode,
    box: { minX, minY, minZ, maxX, maxY, maxZ },
    centre: found.centre
  };
}

/** The chunk coordinates to mesh. */
export function meshRange(range) {
  const out = [];
  for (let cx = range.minCx; cx <= range.maxCx; cx++) for (let cz = range.minCz; cz <= range.maxCz; cz++) out.push([cx, cz]);
  return out;
}

/** Mesh the chunks of a built world. `mesher` is a `ChunkMesher`; returns `[{cx, cz, geo}]`. */
export function meshBuiltWorld(built, mesher, only = null) {
  const wanted = only ?? meshRange(built.range);
  return wanted.map(([cx, cz]) => ({ cx, cz, geo: mesher.meshChunk(built.world.getOrCreateChunk(cx, cz), built.world) }));
}

// ---------------------------------------------------------------------------------------------------------------
// Views for the loot and block-entity panels.

function itemLabel(item) {
  if (!item) return null;
  const def = typeof item.id === 'number' ? BLOCK_DEFS[item.id] : null;
  const name = item.name ?? item.displayName ?? item.item ?? def?.name ?? (typeof item.id === 'string' ? item.id : `item ${item.id}`);
  return { name: String(name), count: item.count ?? 1 };
}

/** Every chest the structure created, with what the game put in it. */
export function lootView(built) {
  const chests = built.recorder.chests.map((chest) => {
    const items = (chest.items ?? []).map(itemLabel).filter(Boolean);
    return {
      pos: chest.pos.map(Math.floor), facing: chest.facing,
      items, stacks: items.length, total: items.reduce((sum, item) => sum + item.count, 0)
    };
  });
  const totals = new Map();
  for (const chest of chests) for (const item of chest.items) totals.set(item.name, (totals.get(item.name) ?? 0) + item.count);
  return {
    chests,
    empty: chests.filter((chest) => chest.stacks === 0).length,
    totals: [...totals].map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count || a.name.localeCompare(b.name))
  };
}

/** The doors, beds, chests and requested mobs: everything the voxel grid cannot carry. */
export function blockEntitiesView(built) {
  const { recorder } = built;
  const FACING = ['north', 'east', 'south', 'west'];
  const rows = [];
  for (const chest of recorder.chests) rows.push({ kind: 'chest', pos: chest.pos.map(Math.floor), detail: `facing ${FACING[chest.facing] ?? chest.facing}, ${(chest.items ?? []).length} stack(s)` });
  for (const door of recorder.doors) rows.push({ kind: 'door', pos: door.pos.map(Math.floor), detail: `facing ${FACING[door.facing] ?? door.facing}, hinge ${door.hinge}` });
  for (const bed of recorder.beds) rows.push({ kind: 'bed', pos: bed.foot.map(Math.floor), detail: `head at ${bed.head.map(Math.floor).join(',')}` });
  for (const mob of recorder.mobs) rows.push({ kind: 'mob', pos: [mob.x, mob.y, mob.z].map(Math.floor), detail: `${mob.type}${mob.options?.variant ? ` (${mob.options.variant})` : ''}${mob.options?.persistent ? ' persistent' : ''}` });
  const counts = {};
  for (const row of rows) counts[row.kind] = (counts[row.kind] ?? 0) + 1;
  return { rows, counts };
}

/** How many blocks of each kind the world holds inside the structure's box (for the evidence export). */
export function boxBlockCounts(built) {
  const { minX, minY, minZ, maxX, maxY, maxZ } = built.box;
  const counts = new Map();
  for (let x = minX; x <= maxX; x++) {
    for (let y = Math.max(0, minY); y <= Math.min(63, maxY); y++) {
      for (let z = minZ; z <= maxZ; z++) {
        const id = built.world.getVoxel(x, y, z);
        if (id === BLOCKS.AIR) continue;
        const name = BLOCK_DEFS[id]?.name ?? `block ${id}`;
        counts.set(name, (counts.get(name) ?? 0) + 1);
      }
    }
  }
  return Object.fromEntries([...counts].sort((a, b) => b[1] - a[1]));
}
